select hhl.*
from hls_price_list_config_ln hhl,hls_price_list_config_hd hhd
where hhd.price_list = #{priceList}
and hhd.table_type = 'SINGLE'
and hhd.config_hd_id = hhl.config_hd_id
and hhl.column_code = #{columnCode}
